from lib import *
S = SS('l12')
steps = [
    step("三个 1 MB 的文件 add 之后的松散对象:文本 text.txt(1,000,050 字节)压缩到 430,279 字节(43.0%);随机字节 random.bin(1,000,000)变成 1,000,324 字节(100.0%,比原文件还大 324 字节:zlib 头部和块开销);全零 zeros.bin 只有 4,395 字节(0.4%)。blob 的体积完全取决于内容的可压缩程度。", t=tl(S(1)), mark=lidx(S(1), 'random.bin', 'zeros.bin'), done=lidx(S(1), 'text.txt'), b=bars([['text.txt(文本)', 430279, '430,279 字节'], ['random.bin(随机)', 1000324, '1,000,324 字节'], ['zeros.bin(全零)', 4395, '4,395 字节']], 1000324, mark=[1], done=[0, 2]), kv=KV([['文本', '压到约 43%'], ['随机字节', '100.0%,反而大 324 字节'], ['全零', '0.4%']], ['随机字节'])),
    step("对 1 MB 文本每次只改一行再提交:v0 之后 objects 目录 430,446 字节,v1 是 860,986(新增 430,540),v2 是 1,291,543,……v5 是 2,583,273。每个版本都是一个完整的松散对象,每次新增约 430 KB,即使只改了一行;git count-objects -v 显示 18 个松散对象(count: 18,size: 2592 KiB),in-pack 0。", t=tl(S(2)), mark=lidx(S(2), '提交 v5 之后', 'count: 18'), done=lidx(S(2), '提交 v0 之后', '提交 v1 之后', '提交 v2 之后', '提交 v3 之后', '提交 v4 之后'), b=bars([['v0', 430446, '0.43 MB'], ['v1', 860986, '0.86 MB'], ['v2', 1291543, '1.29 MB'], ['v3', 1722106, '1.72 MB'], ['v4', 2152685, '2.15 MB'], ['v5', 2583273, '2.58 MB']], 2583273, mark=[5], done=[0, 1, 2, 3, 4]), kv=KV([['松散对象', '每个版本一份完整的压缩副本'], ['每次新增', '约 430 KB(改一行也一样)'], ['6 个版本', '2.58 MB']], ['松散对象'])),
    step("git gc 之后:松散对象 count 0,所有 18 个对象进了 packfile(in-pack: 18),size-pack 380 KiB;objects 目录从 2,583,273 字节降到 391,354 字节,缩小到约 15%。6 个版本之间只差一行,gc 把后面的版本存成对前一个版本的 delta,所以 6 个版本合起来比原来 1 个松散对象还小。", t=tl(S(3)), mark=lidx(S(3), 'in-pack: 18', 'size-pack: 380', '391,354'), done=lidx(S(3), 'count: 0', 'git gc -q'), b=bars([['gc 前', 2583273, '2,583,273 字节'], ['gc 后', 391354, '391,354 字节']], 2583273, mark=[1], done=[0]), kv=KV([['gc 之前', '18 个松散对象,2.58 MB'], ['gc 之后', '1 个 pack,391 KB'], ['原因', '后续版本存成 delta']], ['原因'])),
    step("core.compression 级别对 1 MB 文本的影响:level 0 不压缩,松散对象 1,000,219 字节;level 1 是 430,279(与默认的松散对象压缩相同);level 4 是 390,613;level 6 与 level 9 都是 386,597。add 耗时 18 → 25 → 29 → 32 → 32 ms(每个只跑了一次,含进程启动)。压缩级别从 1 提到 4 省 9%,再往上几乎不变;大部分收益来自 gc 的 delta,不是 zlib 级别。", t=tl(S(4)), mark=lidx(S(4), 'level 0', 'level 9'), done=lidx(S(4), 'level 1', 'level 4', 'level 6'), b=bars([['level 0', 1000219, '1,000,219'], ['level 1', 430279, '430,279'], ['level 4', 390613, '390,613'], ['level 6', 386597, '386,597'], ['level 9', 386597, '386,597']], 1000219, mark=[0], done=[1, 2, 3, 4]), kv=KV([['level 1', '默认(松散对象)'], ['level 4 → 9', '只再省约 1%'], ['耗时', '19 → 34 ms,差别不大']], ['level 1'])),
    step("不可压缩的 1 MB 随机文件改 10 个字节,提交两个版本:gc 前 objects 目录 2,001,016 字节(两个完整副本),gc 后 1,003,371 字节(size-pack 978 KiB):只比一个副本多一点。delta 与压缩无关,按字节差异存储,所以不可压缩的二进制文件也能被 delta 压缩。", t=tl(S(5)), mark=lidx(S(5), 'size-pack: 978', '1,003,371'), done=lidx(S(5), 'gc 前', 'in-pack: 6'), b=bars([['gc 前(2 个版本)', 2001016, '2,001,016 字节'], ['gc 后', 1003371, '1,003,371 字节']], 2001016, mark=[1], done=[0]), kv=KV([['随机内容', '无法压缩'], ['delta', '按差异存储,10 字节改动只多出很少'], ['结论', 'gc 后大文件的小改动代价很小']], ['结论'])),
]
A = mkarti('l12', 12, 'Git,blob,压缩,大文件,gc,delta,真实验证,动画演示',
    '实测 git 存大文件的代价:1 MB 文本松散对象 430,279 字节,随机字节反而大 324 字节,全零 4,395 字节;每次改一行就新增一个完整的 430 KB 副本(6 个版本 2.58 MB),gc 之后降到 391 KB;core.compression 从 1 提到 9 只再省约 10%;随机文件改 10 字节,gc 后两个版本只比一个多一点。',
    '一个 1 MB 的文件在 git 里占多少空间?每改一行会多占多少?这篇测不同类型文件的 blob 大小、每次修改的松散对象增长、gc 之后的缩小,以及压缩级别和随机二进制文件的 delta。',
    [('43%', '1 MB 文本压缩后的松散对象大小占原文件的比例(随机字节是 100.0%)'), ('430 KB', '改一行再提交,松散对象每次新增的大小'), ('2.58 MB → 391 KB', '6 个版本的 objects 目录大小,gc 前后')],
    [('blob 的大小取决于可压缩性', '<p>blob 先 zlib 压缩再存。文本约压到 43%,随机字节没法压缩,反而因为头部多出几百字节,全零几乎不占空间。不要拿原文件大小估算仓库大小。</p>'),
     ('松散对象每版一份', '<p>每提交一个新版本,不管只改了一行还是一万行,都新增一个完整的压缩副本。1 MB 文本改 5 次,objects 目录就是 2.58 MB。松散对象本身没有跨版本的复用。</p>'),
     ('gc 把差异存起来', '<p><code>git gc</code> 把对象打进 packfile,版本之间用 delta 编码。同样 6 个版本,目录从 2.58 MB 缩到 391 KB。这是 git 能放得下很长历史的原因(见后面 packfile 与 delta 的文章)。</p>'),
     ('压缩级别', '<p><code>core.compression</code> 调的是 zlib 级别。默认松散对象用 level 1;提高到 4 省约 9%,再往上几乎无变化,耗时也只是十几毫秒的差别。真正的收益来自 delta,不是调高压缩级别。</p>'),
     ('二进制文件', '<p>delta 按字节差异存储,与可不可压缩无关。1 MB 随机文件改 10 个字节,gc 之后两个版本只比一个版本多一点点。真正会让仓库膨胀的是整个重新生成的大文件(每次内容全变),而不是小改动。</p>')],
    steps,
    [ENV_I_GIT + '。测试数据是固定随机种子生成的 1 MB 文本(随机单词)、随机字节、全零;大小是 .git/objects 下文件的字节数,count-objects 的 size 单位是 KiB;耗时每个级别只测一次,含进程启动',
     '没有验证:真实源代码或图片等文件的压缩率(这里的文本是随机单词拼成的);--depth、--window 对 gc 结果的影响(见 delta 链一篇);core.bigFileThreshold(超过 512 MiB 的文件不做 delta,没有试);Git LFS;压缩耗时的稳定数字(只跑了一次)'],
    '大文件的存储代价')
